  ["setup","sed -n '1,320p' docs/SETUP-GUIDE.md"],
  ["github","sed -n '1,320p' docs/GITHUB-SETUP.md"],
  ["msw","sed -n '1,360p' bin/msw"],
  ["artifact","sed -n '1,360p' artifacts/msw-menu-bar-app-plan.html"],
  ["agents","cat AGENTS.md"]
];
